// Element -> hand-drawn paths, generated by Excalidraw's own shape code (@excalidraw/element ShapeCache: the same
// roughjs options, arrowheads, rounded corners and freedraw outline excalidraw.com draws). This file only turns
// its roughjs drawables into renderer-neutral paints: stroke and fill paths in element-local coordinates
// (origin at element.x/y, unrotated). Sidecar-only: the mod gets the paints over the wire.

import { ShapeCache } from "@excalidraw/element";
import { absolutize, normalize, parsePath } from "path-data-parser";
import type { Drawable, OpSet, ResolvedOptions } from "roughjs/bin/core";
import type { CanvasElement, Paint, PathOp } from "./types.ts";

/** Excalidraw's check: "transparent", #rgb0 or #rrggbb00. */
export const isTransparent = (color: string): boolean =>
  color === "transparent" || (color.length === 5 && color[4] === "0") || (color.length === 9 && color.endsWith("00"));

/** Applies element opacity (0-100) to a #rgb/#rrggbb colour; other colour forms pass through. */
export function withOpacity(color: string, opacity: number): string {
  if (opacity >= 100 || !color.startsWith("#")) return color;
  const hex = color.length === 4 ? [...color.slice(1)].map((c) => c + c).join("") : color.slice(1, 7);
  const alpha = Math.round((Math.max(0, opacity) / 100) * 255)
    .toString(16)
    .padStart(2, "0");
  return `#${hex}${alpha}`;
}

/** One roughjs op set as a paint: "path" is the outline, "fillPath" a solid fill, "fillSketch" hachure strokes. */
function setPaint(set: OpSet, o: ResolvedOptions, opacity: number): Paint | null {
  if (set.type === "path") {
    if (o.stroke === "none") return null;
    return {
      kind: "stroke",
      color: withOpacity(o.stroke, opacity),
      width: o.strokeWidth,
      dash: o.strokeLineDash ?? null,
      ops: set.ops,
    };
  }
  if (!o.fill) return null;
  if (set.type === "fillPath")
    return { kind: "fill", color: withOpacity(o.fill, opacity), width: 0, dash: null, ops: set.ops };
  const width = o.fillWeight < 0 ? o.strokeWidth / 2 : o.fillWeight;
  return { kind: "stroke", color: withOpacity(o.fill, opacity), width, dash: o.fillLineDash ?? null, ops: set.ops };
}

/** An SVG path (Excalidraw's freedraw outline) as move/lineTo/bcurveTo ops. */
function svgOps(d: string): PathOp[] {
  const ops: PathOp[] = [];
  let start: number[] = [0, 0];
  for (const { key, data } of normalize(absolutize(parsePath(d)))) {
    if (key === "M") start = data;
    ops.push({ op: key === "M" ? "move" : key === "C" ? "bcurveTo" : "lineTo", data: key === "Z" ? start : data });
  }
  return ops;
}

type Shape = Drawable | string | null | readonly (Drawable | string | null)[];
const generate = ShapeCache.generateElementShape as unknown as (e: CanvasElement, config: null) => Shape;

/** Renderer-neutral paints for an element: what to stroke and fill, in element-local coordinates. */
export function elementPaints(e: CanvasElement): Paint[] {
  const shape = generate(e, null);
  const parts = Array.isArray(shape) ? shape : [shape];
  const paints: Paint[] = [];
  for (const d of parts) {
    if (typeof d === "string")
      paints.push({ kind: "fill", color: withOpacity(e.strokeColor, e.opacity), width: 0, dash: null, ops: svgOps(d) });
    else if (d)
      for (const set of d.sets) {
        const p = setPaint(set, d.options, e.opacity);
        if (p) paints.push(p);
      }
  }
  return paints;
}

interface Rect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

type Pt = readonly [number, number];
const pt = (d: readonly number[], i = 0): Pt => [d[i] ?? 0, d[i + 1] ?? 0];
const lerp = (a: Pt, b: Pt, t: number): number[] => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];

/** The part of segment a->b inside r, as [t0, t1] along it (Liang-Barsky), or null. */
function inside(a: Pt, b: Pt, r: Rect): [number, number] | null {
  const [dx, dy] = [b[0] - a[0], b[1] - a[1]];
  let [t0, t1] = [0, 1];
  for (const [p, q] of [
    [-dx, a[0] - r.x],
    [dx, r.x + r.width - a[0]],
    [-dy, a[1] - r.y],
    [dy, r.y + r.height - a[1]],
  ] as const) {
    if (p === 0) {
      if (q < 0) return null;
      continue;
    }
    if (p < 0) t0 = Math.max(t0, q / p);
    else t1 = Math.min(t1, q / p);
    if (t0 > t1) return null;
  }
  return [t0, t1];
}

const CURVE_STEPS = 12;

/** Bezier and line ops as polylines, one per subpath. */
function polylines(ops: readonly PathOp[]): Pt[][] {
  const lines: Pt[][] = [];
  let cur: Pt[] = [];
  for (const { op, data } of ops) {
    if (op === "move") {
      cur = [pt(data)];
      lines.push(cur);
    } else if (op === "lineTo") cur.push(pt(data));
    else {
      const [p0, c1, c2, p3] = [cur.at(-1) ?? [0, 0], pt(data), pt(data, 2), pt(data, 4)];
      for (let i = 1; i <= CURVE_STEPS; i++) {
        const t = i / CURVE_STEPS;
        const w = [(1 - t) ** 3, 3 * (1 - t) ** 2 * t, 3 * (1 - t) * t * t, t ** 3] as const;
        cur.push([
          w[0] * p0[0] + w[1] * c1[0] + w[2] * c2[0] + w[3] * p3[0],
          w[0] * p0[1] + w[1] * c1[1] + w[2] * c2[1] + w[3] * p3[1],
        ]);
      }
    }
  }
  return lines;
}

/** Stroke ops with the part inside r removed: Excalidraw hides an arrow's line under its label. */
export function cutOut(ops: readonly PathOp[], r: Rect): PathOp[] {
  const out: PathOp[] = [];
  for (const line of polylines(ops)) {
    let pen = false;
    line.slice(1).forEach((b, i) => {
      const a = line[i] as Pt;
      const hit = inside(a, b, r);
      const keep = hit
        ? (
            [
              [0, hit[0]],
              [hit[1], 1],
            ] as const
          ).filter(([s, e]) => e - s > 1e-6)
        : ([[0, 1]] as const);
      pen &&= keep.length > 0;
      for (const [s, e] of keep) {
        if (!pen || s > 0) out.push({ op: "move", data: lerp(a, b, s) });
        out.push({ op: "lineTo", data: lerp(a, b, e) });
        pen = e === 1;
      }
    });
  }
  return out;
}
